/**
 * Состав сессии. Хранится в зашифрованной cookie, поэтому кладём только
 * идентификаторы: остальное подтягиваем из базы на каждом запросе, чтобы
 * исключение пользователя из организации действовало немедленно.
 *
 * `sid` — случайный идентификатор сессии; его хеш лежит в user_sessions,
 * и по нему сессию можно завершить с другого устройства. Cookie без sid
 * (выданная до появления таблицы) считается недействительной.
 *
 * `pendingUserId` — пароль подошёл, ждём код второго фактора. Живёт
 * несколько минут (pendingAt) и в полноценную сессию не превращается,
 * пока код не сойдётся.
 */
declare module '@fastify/secure-session' {
  interface SessionData {
    userId: string;
    orgId: string;
    sid: string;
    pendingUserId: string;
    pendingAt: number;
  }
}

export {};
